import BpkCalendar from '@skyscanner/bpk-component-calendar';
import BpkButton from '@skyscanner/bpk-component-button';
import format from 'date-fns/format';
import addDays from 'date-fns/addDays';

// Set today's date
const today = new Date();

function App() {
  const [selectedDate, setSelectedDate] = React.useState(today);

  return (
    <div className="App">
      <h1>Flight Schedule</h1>

      <BpkCalendar
        id="calendar"
        onDateSelect={(date) => setSelectedDate(date)}
        selectedDate={selectedDate}
        formatDate={date => format(date, 'dd MMM yyyy')}
        daysOfWeek={[
          'Sunday',
          'Monday',
          'Tuesday',
          'Wednesday',
          'Thursday',
          'Friday',
          'Saturday'
        ]}
        weekStartsOn={0} // Sunday
        changeMonthLabel="Change month"
        showWeekendSeparator
        minDate={today}
        maxDate={addDays(today, 60)} // Optional: limit to next 2 months
      />

      <div className="button-wrapper">
        <BpkButton onClick={() => alert('Button clicked!')}>
          Continue
        </BpkButton>
      </div>
    </div>
  );
}

export default App;
